import React, { memo, useEffect, useMemo, useRef, useState } from 'react';
import {
  ArrowDownUp, Bold, ChevronDown, ChevronRight, Code2, Copy, Download,
  FilePlus2, FileText, FileUp, FolderPlus, Heading2, Image, Italic, Link2, List,
  ListChecks, MessageSquarePlus, Paperclip, Plus, Search, Sparkles, Star,
  Table2, Trash2, Undo2, Video, X
} from 'lucide-react';
import { createId, createProject, loadProjects, updateProject } from './projectsData.js';
import { deleteStoredFile, getStoredFile, storeFile } from './fileStore.js';

const COLUMN_TYPES = ['Texto', 'Número', 'Fecha', 'Estado', 'Casilla', 'Etiqueta', 'Persona', 'Archivo', 'URL', 'Lista', 'Moneda', 'Progreso', 'Relación', 'Fórmula'];
const SALES_STATUSES = ['new', 'researching', 'called', 'no_answer', 'callback', 'interested', 'meeting', 'proposal', 'closed', 'lost', 'wrong_number', 'not_interested', 'dead'];
const SALES_STAGES = ['Prospecto', 'Contacto', 'Interesado', 'Demostración', 'Propuesta', 'Negociación', 'Ganado', 'Perdido'];
const STATUS_LABELS = { new: 'Nuevo', researching: 'Investigando', called: 'Llamado', no_answer: 'No contestó', interested: 'Interesado', callback: 'Devolver llamada', meeting: 'Reunión', proposal: 'Propuesta', closed: 'Ganado', sale: 'Venta', lost: 'Perdido', wrong_number: 'Número incorrecto', not_interested: 'No interesado', dead: 'Descartado' };

function downloadText(name, content, type = 'text/plain') {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const anchor = document.createElement('a');
  anchor.href = url; anchor.download = name; anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 500);
}

function escapeCsv(value) {
  const text = String(value ?? '');
  return /[",\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

function parseCsv(text) {
  const rows = []; let row = []; let field = ''; let quoted = false;
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    if (char === '"' && quoted && text[index + 1] === '"') { field += '"'; index += 1; }
    else if (char === '"') quoted = !quoted;
    else if (char === ',' && !quoted) { row.push(field); field = ''; }
    else if ((char === '\n' || char === '\r') && !quoted) {
      if (char === '\r' && text[index + 1] === '\n') index += 1;
      row.push(field); if (row.some((cell) => cell.trim())) rows.push(row); row = []; field = '';
    } else field += char;
  }
  row.push(field); if (row.some((cell) => cell.trim())) rows.push(row);
  return rows;
}

function plainText(html = '') {
  const element = document.createElement('div'); element.innerHTML = html;
  return element.textContent || '';
}

export function DocumentEditor({ project, module, onChange }) {
  const editorRef = useRef(null);
  const saveTimer = useRef(null);
  const [query, setQuery] = useState('');
  const [comment, setComment] = useState('');
  const content = module.content || {};
  useEffect(() => { if (editorRef.current && editorRef.current.innerHTML !== (content.html || '')) editorRef.current.innerHTML = content.html || ''; }, [module.id]);
  useEffect(() => () => window.clearTimeout(saveTimer.current), []);
  const save = () => {
    const html = editorRef.current?.innerHTML || '';
    if (html !== (content.html || '')) onChange({ content: { ...content, html, revision: (content.revision || 1) + 1 } }, 'Documento guardado');
  };
  const queueSave = () => { window.clearTimeout(saveTimer.current); saveTimer.current = window.setTimeout(save, 900); };
  const command = (name, value) => { editorRef.current?.focus(); document.execCommand(name, false, value); queueSave(); };
  const headings = useMemo(() => {
    const holder = document.createElement('div'); holder.innerHTML = content.html || '';
    return [...holder.querySelectorAll('h1,h2,h3')].map((heading, index) => ({ id: index, text: heading.textContent }));
  }, [content.html]);
  const visibleText = plainText(content.html).toLocaleLowerCase('es');
  const addComment = () => { if (!comment.trim()) return; onChange({ content: { ...content, comments: [...(content.comments || []), { id: createId('comment'), text: comment.trim(), at: new Date().toISOString() }] } }, 'Comentario añadido'); setComment(''); };
  const attach = async (file) => { if (!file) return; const id = createId('attachment'); await storeFile({ id, projectId: project.id, moduleId: module.id, file }); onChange({ content: { ...content, attachments: [...(content.attachments || []), { id, name: file.name, type: file.type, size: file.size }] } }, 'Archivo adjuntado al documento'); };
  const openAttachment = async (attachment) => { const stored = await getStoredFile(attachment.id); if (!stored?.blob) return; const url = URL.createObjectURL(stored.blob); window.open(url, '_blank', 'noopener,noreferrer'); window.setTimeout(() => URL.revokeObjectURL(url), 60_000); };
  return <div className="document-editor-v1">
    <div className="document-toolbar">
      <button onClick={() => command('formatBlock', 'h2')} title="Encabezado"><Heading2 size={14} /></button>
      <button onClick={() => command('bold')} title="Negrita"><Bold size={14} /></button>
      <button onClick={() => command('italic')} title="Cursiva"><Italic size={14} /></button>
      <button onClick={() => command('insertUnorderedList')} title="Lista"><List size={14} /></button>
      <button onClick={() => command('insertHTML', '<label><input type="checkbox"> Pendiente</label><br>')} title="Lista de control"><ListChecks size={14} /></button>
      <button onClick={() => command('insertHTML', '<pre><code>Escribe código aquí</code></pre><p><br></p>')} title="Código"><Code2 size={14} /></button>
      <button onClick={() => command('insertHTML', '<table><tbody><tr><th>Columna</th><th>Columna</th></tr><tr><td>Dato</td><td>Dato</td></tr></tbody></table><p><br></p>')} title="Tabla"><Table2 size={14} /></button>
      <button onClick={() => { const url = window.prompt('Dirección del enlace'); if (url) command('createLink', url); }} title="Enlace"><Link2 size={14} /></button>
      <button onClick={() => { const url = window.prompt('Dirección de la imagen'); if (url) command('insertImage', url); }} title="Imagen"><Image size={14} /></button>
      <button onClick={() => { const url = window.prompt('Dirección del video'); if (url) command('insertHTML', `<video controls src="${url}"></video><p><br></p>`); }} title="Video incrustado"><Video size={14} /></button>
      <button onClick={() => { const url = window.prompt('Dirección del PDF'); if (url) command('insertHTML', `<iframe src="${url}" title="Documento PDF"></iframe><p><br></p>`); }} title="PDF incrustado"><FileText size={14} /></button>
      <label className="document-attachment" title="Adjuntar archivo"><Paperclip size={14} /><input type="file" onChange={(event) => attach(event.target.files?.[0])} /></label>
      <label className="document-search"><Search size={13} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar dentro…" /></label>
      <span className={query && visibleText.includes(query.toLocaleLowerCase('es')) ? 'is-found' : ''}>{query ? (visibleText.includes(query.toLocaleLowerCase('es')) ? 'Encontrado' : 'Sin coincidencias') : `Versión ${content.revision || 1}`}</span>
    </div>
    <div className="document-layout">
      <aside><span>Índice</span>{headings.map((heading) => <button key={heading.id}>{heading.text}</button>)}{!headings.length ? <small>Los encabezados aparecerán aquí.</small> : null}</aside>
      <div ref={editorRef} className="rich-document" contentEditable suppressContentEditableWarning onInput={queueSave} onBlur={save} data-placeholder="Escribe. El documento se guarda mientras trabajas." />
      <aside className="document-comments"><span>Comentarios</span>{(content.comments || []).map((item) => <p key={item.id}>{item.text}</p>)}<textarea value={comment} onChange={(event) => setComment(event.target.value)} placeholder="Añadir contexto…" /><button onClick={addComment}><MessageSquarePlus size={12} /> Comentar</button><span>Adjuntos</span>{(content.attachments || []).map((item) => <button key={item.id} onClick={() => openAttachment(item)}><Paperclip size={11} /> {item.name}</button>)}</aside>
    </div>
    <div className="document-export"><button onClick={() => window.print()}><Download size={12} /> Imprimir o PDF</button><button onClick={() => downloadText(`${module.title}.md`, plainText(content.html), 'text/markdown')}><Download size={12} /> Markdown</button><button onClick={() => downloadText(`${module.title}.txt`, plainText(content.html))}><Download size={12} /> Texto</button></div>
  </div>;
}

export function FilesEditor({ project, module, onChange }) {
  const content = module.content || {}; const files = content.files || []; const trash = content.trash || [];
  const [busy, setBusy] = useState(false); const [query, setQuery] = useState(''); const [view, setView] = useState(module.view || 'Lista'); const [preview, setPreview] = useState(null); const [showTrash, setShowTrash] = useState(false); const [sortMode, setSortMode] = useState('Recientes');
  useEffect(() => () => { if (preview?.url) URL.revokeObjectURL(preview.url); }, [preview]);
  const commit = (next, reason) => onChange({ content: { ...content, ...next } }, reason);
  const importFiles = async (list) => { const incoming = [...list]; if (!incoming.length) return; setBusy(true); const metadata = [];
    for (const file of incoming) { const id = createId('file'); await storeFile({ id, projectId: project.id, moduleId: module.id, file }); metadata.push({ id, name: file.name, size: file.size, type: file.type || 'Archivo', createdAt: new Date().toISOString(), favorite: false, tags: [] }); }
    commit({ files: [...files, ...metadata] }, `${incoming.length} archivos añadidos`); setBusy(false);
  };
  const open = async (file) => { const stored = await getStoredFile(file.id); if (!stored?.blob) return; if (preview?.url) URL.revokeObjectURL(preview.url); setPreview({ url: URL.createObjectURL(stored.blob), type: stored.type || '', name: file.name }); };
  const duplicate = async (file) => { const stored = await getStoredFile(file.id); if (!stored?.blob) return; const id = createId('file'); const name = `${file.name.replace(/(\.[^.]+)$/, '')} — copia${file.name.match(/(\.[^.]+)$/)?.[1] || ''}`; const copy = new File([stored.blob], name, { type: stored.type }); await storeFile({ id, projectId: project.id, moduleId: module.id, file: copy }); commit({ files: [...files, { ...file, id, name, createdAt: new Date().toISOString() }] }, 'Archivo duplicado'); };
  const shown = [...(showTrash ? trash : files).filter((file) => `${file.name} ${(file.tags || []).join(' ')}`.toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es')))].sort((a, b) => sortMode === 'Nombre' ? a.name.localeCompare(b.name, 'es') : sortMode === 'Favoritos' ? Number(Boolean(b.favorite)) - Number(Boolean(a.favorite)) : String(b.createdAt).localeCompare(String(a.createdAt)));
  return <div className="files-v1"><div className="module-actionbar"><label><Search size={13} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar archivos o etiquetas…" /></label><button onClick={() => setView(view === 'Lista' ? 'Cuadrícula' : 'Lista')}>{view}</button><select value={sortMode} onChange={(event) => setSortMode(event.target.value)}><option>Recientes</option><option>Nombre</option><option>Favoritos</option></select><button className={showTrash ? 'is-active' : ''} onClick={() => setShowTrash(!showTrash)}><Trash2 size={12} /> Papelera {trash.length}</button></div>
    {!showTrash ? <label className="file-drop" onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); importFiles(event.dataTransfer.files); }}><FileUp size={20} /><strong>{busy ? 'Guardando…' : 'Suelta archivos aquí'}</strong><span>Subida múltiple y almacenamiento local.</span><input type="file" multiple onChange={(event) => importFiles(event.target.files)} /></label> : null}
    <div className={`stored-files-v1 is-${view.toLocaleLowerCase('es')}`}>{shown.map((file) => <article key={file.id}><button className="file-main" onClick={() => !showTrash && open(file)}><FilePlus2 size={17} /><span><strong>{file.name}</strong><small>{Math.max(1, Math.round(file.size / 1024))} kB{file.tags?.length ? ` · ${file.tags.join(', ')}` : ''}</small></span></button>{showTrash ? <><button onClick={() => commit({ files: [...files, file], trash: trash.filter((item) => item.id !== file.id) }, 'Archivo restaurado')}><Undo2 size={12} /></button><button onClick={async () => { await deleteStoredFile(file.id); commit({ trash: trash.filter((item) => item.id !== file.id) }, 'Archivo eliminado definitivamente'); }}><Trash2 size={12} /></button></> : <><button className={file.favorite ? 'is-active' : ''} onClick={() => commit({ files: files.map((item) => item.id === file.id ? { ...item, favorite: !item.favorite } : item) }, 'Favorito actualizado')}><Star size={12} /></button><button onClick={() => duplicate(file)}><Copy size={12} /></button><button title="Renombrar" onClick={() => { const name = window.prompt('Nuevo nombre', file.name); if (name) commit({ files: files.map((item) => item.id === file.id ? { ...item, name } : item) }, 'Archivo renombrado'); }}><FilePlus2 size={12} /></button><button title="Etiquetar" onClick={() => { const tags = window.prompt('Etiquetas separadas por comas', (file.tags || []).join(', ')); if (tags !== null) commit({ files: files.map((item) => item.id === file.id ? { ...item, tags: tags.split(',').map((tag) => tag.trim()).filter(Boolean) } : item) }, 'Etiquetas actualizadas'); }}><Sparkles size={12} /></button><button onClick={() => commit({ files: files.filter((item) => item.id !== file.id), trash: [...trash, file] }, 'Archivo movido a la papelera')}><Trash2 size={12} /></button></>}</article>)}</div>
    {preview ? <section className="local-file-preview"><header><span>{preview.name}</span><button onClick={() => setPreview(null)}><X size={13} /></button></header>{preview.type.startsWith('image/') ? <img src={preview.url} alt={preview.name} /> : preview.type.startsWith('video/') ? <video src={preview.url} controls /> : preview.type.startsWith('audio/') ? <audio src={preview.url} controls /> : <iframe src={preview.url} title={`Vista previa de ${preview.name}`} />}</section> : null}
  </div>;
}

function FolderBranch({ folder, folders, expanded, toggle, rename, remove, depth = 0 }) {
  const children = folders.filter((item) => item.parentId === folder.id); const open = expanded.has(folder.id);
  return <div className="folder-branch"><div style={{ '--folder-depth': depth }}><button onClick={() => toggle(folder.id)}>{children.length ? (open ? <ChevronDown size={13} /> : <ChevronRight size={13} />) : <span />}</button><FolderPlus size={15} /><strong>{folder.title}</strong><small>{children.length}</small><button onClick={() => rename(folder)}><FilePlus2 size={11} /></button><button onClick={() => remove(folder.id)}><Trash2 size={11} /></button></div>{open ? children.map((child) => <FolderBranch key={child.id} folder={child} folders={folders} expanded={expanded} toggle={toggle} rename={rename} remove={remove} depth={depth + 1} />) : null}</div>;
}

export function FoldersEditor({ module, onChange }) {
  const folders = module.content?.folders || []; const [parentId, setParentId] = useState(null); const [expanded, setExpanded] = useState(new Set());
  const commit = (next, reason) => onChange({ content: { ...module.content, folders: next } }, reason);
  const add = () => { const title = window.prompt('Nombre de la carpeta'); if (!title) return; commit([...folders, { id: createId('folder'), title, parentId, color: 'azul' }], 'Carpeta creada'); };
  const remove = (id) => { const descendants = new Set([id]); let changed = true; while (changed) { changed = false; folders.forEach((folder) => { if (descendants.has(folder.parentId) && !descendants.has(folder.id)) { descendants.add(folder.id); changed = true; } }); } commit(folders.filter((folder) => !descendants.has(folder.id)), 'Carpeta eliminada'); };
  return <div className="folders-v1"><div className="module-actionbar"><button onClick={add}><FolderPlus size={13} /> Nueva carpeta</button><select value={parentId || ''} onChange={(event) => setParentId(event.target.value || null)}><option value="">En la raíz</option>{folders.map((folder) => <option key={folder.id} value={folder.id}>Dentro de {folder.title}</option>)}</select><span>{folders.length} carpetas</span></div><div className="folder-tree">{folders.filter((folder) => !folder.parentId).map((folder) => <FolderBranch key={folder.id} folder={folder} folders={folders} expanded={expanded} toggle={(id) => setExpanded((current) => { const next = new Set(current); next.has(id) ? next.delete(id) : next.add(id); return next; })} rename={(item) => { const title = window.prompt('Nuevo nombre', item.title); if (title) commit(folders.map((folder) => folder.id === item.id ? { ...folder, title } : folder), 'Carpeta renombrada'); }} remove={remove} />)}{!folders.length ? <p>Crea una raíz únicamente cuando la necesites.</p> : null}</div></div>;
}

function cellInput(column, value, onCommit) {
  if (column.type === 'Casilla') return <input type="checkbox" checked={Boolean(value)} onChange={(event) => onCommit(event.target.checked)} />;
  if (column.type === 'Fecha') return <input type="date" defaultValue={value || ''} onBlur={(event) => onCommit(event.target.value)} />;
  if (column.type === 'Número' || column.type === 'Moneda' || column.type === 'Progreso') return <input type="number" defaultValue={value || ''} onBlur={(event) => onCommit(event.target.value)} />;
  return <input defaultValue={value || ''} onBlur={(event) => onCommit(event.target.value)} placeholder="Vacío" />;
}

export function DatabaseEditor({ module, onChange }) {
  const content = module.content || {}; const columns = content.columns || []; const rows = content.rows || [];
  const [query, setQuery] = useState(''); const [selected, setSelected] = useState(new Set()); const [sort, setSort] = useState(null);
  const commit = (next, reason) => onChange({ content: { ...content, ...next } }, reason);
  const visible = useMemo(() => { let next = rows.filter((row) => JSON.stringify(row.values).toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es'))); if (sort) next = [...next].sort((a, b) => String(a.values?.[sort] || '').localeCompare(String(b.values?.[sort] || ''), 'es')); return next; }, [query, rows, sort]);
  const exportCsv = () => downloadText(`${module.title}.csv`, [columns.map((column) => escapeCsv(column.title)).join(','), ...rows.map((row) => columns.map((column) => escapeCsv(row.values?.[column.id])).join(','))].join('\n'), 'text/csv');
  const importCsv = async (file) => { const parsed = parseCsv(await file.text()); if (!parsed.length) return; const nextColumns = parsed[0].map((title) => ({ id: createId('column'), title: title || 'Propiedad', type: 'Texto' })); const nextRows = parsed.slice(1).map((cells) => ({ id: createId('row'), values: Object.fromEntries(nextColumns.map((column, index) => [column.id, cells[index] || ''])) })); commit({ columns: nextColumns, rows: [...rows, ...nextRows] }, 'CSV importado'); };
  return <div className="database-v1"><div className="module-actionbar"><label><Search size={13} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar registros…" /></label><button onClick={() => commit({ columns: [...columns, { id: createId('column'), title: `Propiedad ${columns.length + 1}`, type: 'Texto' }] }, 'Propiedad añadida')}><Plus size={12} /> Propiedad</button><button onClick={() => commit({ rows: [...rows, { id: createId('row'), values: {} }] }, 'Registro añadido')}><Plus size={12} /> Registro</button><select value={content.groupBy || ''} onChange={(event) => commit({ groupBy: event.target.value }, 'Agrupación actualizada')}><option value="">Sin agrupar</option>{columns.map((column) => <option key={column.id} value={column.id}>Agrupar por {column.title}</option>)}</select><label className="file-button"><FileUp size={12} /> Importar CSV<input type="file" accept=".csv,text/csv" onChange={(event) => event.target.files?.[0] && importCsv(event.target.files[0])} /></label><button onClick={exportCsv}><Download size={12} /> Exportar</button>{selected.size ? <><button onClick={() => { commit({ rows: [...rows, ...rows.filter((row) => selected.has(row.id)).map((row) => ({ ...structuredClone(row), id: createId('row') }))] }, 'Registros duplicados'); setSelected(new Set()); }}><Copy size={12} /> Duplicar</button><button onClick={() => { commit({ rows: rows.filter((row) => !selected.has(row.id)) }, 'Registros eliminados'); setSelected(new Set()); }}><Trash2 size={12} /> {selected.size}</button></> : null}</div>
    <div className="database-scroll"><table className="smart-table"><thead><tr><th><input type="checkbox" checked={Boolean(visible.length) && selected.size === visible.length} onChange={() => setSelected(selected.size === visible.length ? new Set() : new Set(visible.map((row) => row.id)))} /></th>{columns.map((column) => <th key={column.id}><input defaultValue={column.title} onBlur={(event) => commit({ columns: columns.map((item) => item.id === column.id ? { ...item, title: event.target.value } : item) }, 'Propiedad renombrada')} /><select value={column.type} onChange={(event) => commit({ columns: columns.map((item) => item.id === column.id ? { ...item, type: event.target.value } : item) }, 'Tipo de propiedad actualizado')}>{COLUMN_TYPES.map((type) => <option key={type}>{type}</option>)}</select><button onClick={() => setSort(sort === column.id ? null : column.id)}><ArrowDownUp size={11} /></button></th>)}</tr></thead><tbody>{visible.map((row) => <tr key={row.id} data-group={content.groupBy ? row.values?.[content.groupBy] || 'Sin grupo' : undefined}><td><input type="checkbox" checked={selected.has(row.id)} onChange={() => setSelected((current) => { const next = new Set(current); next.has(row.id) ? next.delete(row.id) : next.add(row.id); return next; })} /></td>{columns.map((column) => <td key={column.id}>{cellInput(column, row.values?.[column.id], (value) => commit({ rows: rows.map((item) => item.id === row.id ? { ...item, values: { ...item.values, [column.id]: value } } : item) }, 'Base de datos actualizada'))}</td>)}</tr>)}</tbody></table></div><footer>{visible.length} registros · {columns.length} propiedades · {content.groupBy ? `${new Set(visible.map((row) => row.values?.[content.groupBy] || 'Sin grupo')).size} grupos` : 'vista libre'}</footer></div>;
}

export function ChecklistEditor({ module, onChange }) {
  const items = module.content?.items || []; const [draft, setDraft] = useState(''); const [filter, setFilter] = useState('Todos');
  const commit = (next, reason) => onChange({ content: { ...module.content, items: next } }, reason);
  const visible = items.filter((item) => filter === 'Todos' || (filter === 'Pendientes' ? !item.done : item.done));
  const add = (parentId = null) => { const text = parentId ? window.prompt('Nombre de la subtarea') : draft; if (!text?.trim()) return; commit([...items, { id: createId('task'), text: text.trim(), done: false, priority: 'Media', due: '', tags: '', repeat: 'Nunca', parentId }], parentId ? 'Subtarea añadida' : 'Tarea añadida'); if (!parentId) setDraft(''); };
  const move = (id, direction) => { const index = items.findIndex((item) => item.id === id); const target = index + direction; if (target < 0 || target >= items.length) return; const next = [...items]; [next[index], next[target]] = [next[target], next[index]]; commit(next, 'Orden manual actualizado'); };
  return <div className="checklist-v1"><div className="checklist-compose"><input value={draft} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => event.key === 'Enter' && add()} placeholder="Siguiente movimiento…" /><select value={filter} onChange={(event) => setFilter(event.target.value)}><option>Todos</option><option>Pendientes</option><option>Completados</option></select><button onClick={() => add()}><Plus size={13} /></button></div><div className="task-list">{visible.map((item) => <article key={item.id} className={`${item.done ? 'is-done' : ''} ${item.parentId ? 'is-subtask' : ''}`}><input type="checkbox" checked={item.done} onChange={() => commit(items.map((current) => current.id === item.id ? { ...current, done: !current.done } : current), 'Tarea actualizada')} /><input defaultValue={item.text} onBlur={(event) => commit(items.map((current) => current.id === item.id ? { ...current, text: event.target.value } : current), 'Tarea editada')} /><select value={item.priority} onChange={(event) => commit(items.map((current) => current.id === item.id ? { ...current, priority: event.target.value } : current), 'Prioridad actualizada')}><option>Alta</option><option>Media</option><option>Baja</option></select><input type="date" value={item.due || ''} onChange={(event) => commit(items.map((current) => current.id === item.id ? { ...current, due: event.target.value } : current), 'Fecha actualizada')} /><input className="task-tags" defaultValue={item.tags || ''} onBlur={(event) => commit(items.map((current) => current.id === item.id ? { ...current, tags: event.target.value } : current), 'Etiquetas actualizadas')} placeholder="Etiquetas" /><select className="task-repeat" value={item.repeat || 'Nunca'} onChange={(event) => commit(items.map((current) => current.id === item.id ? { ...current, repeat: event.target.value } : current), 'Repetición actualizada')}><option>Nunca</option><option>Diaria</option><option>Semanal</option><option>Mensual</option></select><nav><button title="Subtarea" onClick={() => add(item.id)}><Plus size={10} /></button><button title="Subir" onClick={() => move(item.id, -1)}>↑</button><button title="Bajar" onClick={() => move(item.id, 1)}>↓</button><button title="Eliminar" onClick={() => commit(items.filter((current) => current.id !== item.id && current.parentId !== item.id), 'Tarea eliminada')}><X size={10} /></button></nav></article>)}</div><footer>{items.filter((item) => item.done).length} de {items.length} completadas</footer></div>;
}

export function GoalsEditor({ module, onChange }) {
  const goals = module.content?.goals || []; const commit = (next, reason) => onChange({ content: { ...module.content, goals: next } }, reason);
  const add = () => commit([...goals, { id: createId('goal'), title: 'Nuevo objetivo', progress: 0, start: '', due: '', status: 'En curso', results: [] }], 'Objetivo creado');
  return <div className="goals-v1"><button className="primary-module-action" onClick={add}><Plus size={13} /> Nuevo objetivo</button><div>{goals.map((goal) => <article key={goal.id}><div className="goal-orbit" style={{ '--goal-progress': `${goal.progress}%` }}><strong>{goal.progress}%</strong></div><section><input defaultValue={goal.title} onBlur={(event) => commit(goals.map((item) => item.id === goal.id ? { ...item, title: event.target.value } : item), 'Objetivo actualizado')} /><div><select value={goal.status} onChange={(event) => commit(goals.map((item) => item.id === goal.id ? { ...item, status: event.target.value } : item), 'Estado actualizado')}><option>En curso</option><option>En pausa</option><option>Completado</option></select><input type="date" value={goal.start || ''} onChange={(event) => commit(goals.map((item) => item.id === goal.id ? { ...item, start: event.target.value } : item), 'Inicio actualizado')} /><input type="date" value={goal.due || ''} onChange={(event) => commit(goals.map((item) => item.id === goal.id ? { ...item, due: event.target.value } : item), 'Fecha actualizada')} /><button onClick={() => { const title = window.prompt('Resultado clave'); if (title) commit(goals.map((item) => item.id === goal.id ? { ...item, results: [...(item.results || []), { id: createId('result'), title, done: false }] } : item), 'Resultado clave añadido'); }}><Plus size={10} /> Resultado</button></div><input type="range" min="0" max="100" value={goal.progress} onChange={(event) => commit(goals.map((item) => item.id === goal.id ? { ...item, progress: Number(event.target.value) } : item), 'Progreso actualizado')} /><div className="key-results">{(goal.results || []).map((result) => <label key={result.id}><input type="checkbox" checked={result.done} onChange={() => commit(goals.map((item) => item.id === goal.id ? { ...item, results: item.results.map((current) => current.id === result.id ? { ...current, done: !current.done } : current) } : item), 'Resultado clave actualizado')} /> {result.title}</label>)}</div></section><button onClick={() => commit(goals.filter((item) => item.id !== goal.id), 'Objetivo eliminado')}><Trash2 size={12} /></button></article>)}</div>{!goals.length ? <p>Define el resultado, no la lista de tareas.</p> : null}</div>;
}

export function NotesEditor({ project, module, onChange }) {
  const notes = module.content?.notes || []; const [draft, setDraft] = useState(''); const commit = (next, reason) => onChange({ content: { ...module.content, notes: next } }, reason);
  const add = () => { if (!draft.trim()) return; commit([{ id: createId('note'), text: draft.trim(), color: 'azul', tags: [], reminder: '', createdAt: new Date().toISOString() }, ...notes], 'Nota capturada'); setDraft(''); };
  const convertNote = (note, type) => updateProject(project.id, 'Nota transformada', (draftProject) => {
    const index = draftProject.modules.length; const title = note.text.slice(0, 44); const base = { id: createId('module'), type, title, x: 44 + (index % 3) * 340, y: 76 + Math.floor(index / 3) * 260, width: 310, height: 220, view: type === 'document' ? 'Edición' : type === 'database' ? 'Tabla' : type === 'checklist' ? 'Lista' : 'Órbita', parentId: null, groupId: module.groupId || null, pinned: false, hidden: false, minimized: false, maximized: false, zIndex: index + 1, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() };
    if (type === 'document') base.content = { html: `<p>${note.text}</p>`, comments: [], attachments: [], revision: 1 };
    if (type === 'database') base.content = { columns: [{ id: createId('column'), title: 'Nombre', type: 'Texto' }], rows: [{ id: createId('row'), values: {} }], filters: [], groupBy: '' };
    if (type === 'checklist') base.content = { items: [{ id: createId('task'), text: note.text, done: false, priority: 'Media', due: '', tags: [] }] };
    if (type === 'goals') base.content = { goals: [{ id: createId('goal'), title: note.text, progress: 0, status: 'En curso', results: [] }] };
    draftProject.modules.push(base); draftProject.relations.push({ id: createId('relation'), from: module.id, to: base.id, label: 'Transformación' }); return draftProject;
  });
  return <div className="notes-v1"><div className="note-compose"><textarea value={draft} onChange={(event) => setDraft(event.target.value)} placeholder="Captura una idea antes de que desaparezca…" /><button onClick={add}><Plus size={13} /> Guardar nota</button></div><div className="note-grid">{notes.map((note) => <article key={note.id}><textarea defaultValue={note.text} onBlur={(event) => commit(notes.map((item) => item.id === note.id ? { ...item, text: event.target.value } : item), 'Nota actualizada')} /><footer><span>Convertir en</span><button onClick={() => convertNote(note, 'document')}>Documento</button><button onClick={() => convertNote(note, 'checklist')}>Lista</button><button onClick={() => convertNote(note, 'goals')}>Objetivo</button><button onClick={() => commit(notes.filter((item) => item.id !== note.id), 'Nota eliminada')}><Trash2 size={11} /></button></footer></article>)}</div></div>;
}

export function IntelligenceEditor({ project, module, onChange }) {
  const [running, setRunning] = useState(''); const findings = module.content?.findings || [];
  const analyze = (kind) => { setRunning(kind); window.setTimeout(() => { const modules = project.modules.filter((item) => item.id !== module.id); const texts = modules.map((item) => JSON.stringify(item.content || {})).join(' '); const result = kind === 'Riesgos' ? (project.modules.filter((item) => item.hidden).length ? 'Hay información oculta que podría quedar fuera de las decisiones activas.' : 'No aparecen bloqueos estructurales; conviene revisar fechas y tareas vencidas.') : kind === 'Relaciones' ? `${project.relations.length} conexiones explícitas y ${modules.length} fuentes forman el contexto disponible.` : kind === 'Duplicados' ? (new Set(modules.map((item) => item.title.toLowerCase())).size < modules.length ? 'Existen módulos con nombres repetidos; podrían compartir una única fuente.' : 'No se detectaron títulos duplicados.') : texts.length > 200 ? `El proyecto concentra contexto en ${modules.length} módulos. El siguiente paso útil es conectar objetivos con ejecución.` : 'Aún hay poco contexto. Añade contenido antes de pedir una síntesis profunda.'; const finding = { id: createId('finding'), kind, text: result, at: new Date().toISOString() }; onChange({ content: { ...module.content, findings: [finding, ...findings].slice(0, 20), lastRun: finding.at } }, `Análisis ejecutado: ${kind}`); setRunning(''); }, 380); };
  return <div className="intelligence-v1"><div className="intelligence-actions">{['Resumen ejecutivo', 'Relaciones', 'Riesgos', 'Duplicados', 'Siguientes pasos'].map((kind) => <button key={kind} onClick={() => analyze(kind)} disabled={Boolean(running)}><Sparkles size={14} /><strong>{kind}</strong><small>{running === kind ? 'Analizando contexto…' : 'Usar solo este proyecto'}</small></button>)}</div><section><span>Hallazgos</span>{findings.map((finding) => <article key={finding.id}><i /><div><strong>{finding.kind}</strong><p>{finding.text}</p></div></article>)}{!findings.length ? <p>La inteligencia permanece silenciosa hasta que solicites un análisis.</p> : null}</section></div>;
}

export function SubprojectsEditor({ project, module, onChange }) {
  const all = loadProjects(); const ids = module.content?.projectIds || []; const children = ids.map((id) => all.find((item) => item.id === id)).filter(Boolean);
  const create = () => { const title = window.prompt('Nombre del subproyecto'); if (!title) return; const created = createProject({ title, description: `Subproyecto de ${project.title}` })[0]; onChange({ content: { ...module.content, projectIds: [...ids, created.id] } }, 'Subproyecto conectado'); };
  return <div className="subprojects-v1"><button className="primary-module-action" onClick={create}><Plus size={13} /> Crear subproyecto</button><div>{children.map((child, index) => <article key={child.id} style={{ '--subproject-index': index }}><span><i /></span><section><strong>{child.title}</strong><small>{child.modules.length} módulos · {child.description}</small></section><button onClick={() => onChange({ content: { ...module.content, projectIds: ids.filter((id) => id !== child.id) } }, 'Subproyecto desconectado')}><X size={11} /></button></article>)}</div>{!children.length ? <p>Divide el universo sin perder su procedencia.</p> : null}</div>;
}

function salesMetrics(leads, calls) {
  const count = (statuses) => leads.filter((lead) => statuses.includes(lead.status)).length;
  const outcomeCount = (statuses) => calls.filter((call) => statuses.includes(call.outcome)).length;
  const contacted = calls.length; const conversations = outcomeCount(['interested','callback','meeting','proposal','closed','sale']);
  const interested = count(['interested','callback','meeting','proposal']); const meetings = count(['meeting','proposal','closed','sale']); const proposals = count(['proposal','closed','sale']); const closed = count(['closed','sale']);
  const rate = (value, total) => total ? Math.round(value / total * 100) : 0;
  return { total: leads.length, calls: calls.length, contacted, conversations, interested, meetings, proposals, callbacks: count(['callback']), closed, contactRate: rate(contacted, leads.length), interestedRate: rate(interested, contacted), meetingRate: rate(meetings, interested), proposalRate: rate(proposals, meetings), conversionRate: rate(closed, proposals || contacted), averageDuration: calls.length ? Math.round(calls.reduce((sum, call) => sum + Number(call.duration_seconds || 0), 0) / calls.length) : 0 };
}

function SalesRecords({ module, content, commit }) {
  const leads = content.leads || []; const [query, setQuery] = useState(''); const [status, setStatus] = useState('all'); const [selected, setSelected] = useState(new Set());
  const visible = leads.filter((lead) => (status === 'all' || lead.status === status) && JSON.stringify(lead).toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es')));
  const add = () => commit({ leads: [{ id: createId('lead'), business_name: 'Nueva empresa', company: '', sector: '', city: '', website: '', social_links: '', contact_name: '', contact_role: '', phone: '', whatsapp: '', email: '', status: 'new', priority: 'media', pipeline_stage: 'Prospecto', budget: '', probability: '', next_follow_up_at: '', notes: '', objections: '', call_count: 0, last_call_at: null, next_call_at: null, created_at: new Date().toISOString() }, ...leads] }, 'Prospecto creado');
  const importCsv = async (file) => { const rows = parseCsv(await file.text()); if (rows.length < 2) return; const headers = rows[0].map((header) => header.trim().toLowerCase()); const stageNames = { Lead: 'Prospecto', Demo: 'Demostración', Negociacion: 'Negociación' }; const priorityNames = { high: 'alta', medium: 'media', low: 'baja' }; const incoming = rows.slice(1).map((cells) => { const record = Object.fromEntries(headers.map((header, index) => [header, cells[index] || ''])); return { id: createId('lead'), business_name: record.business_name || record.company || record.empresa || record.nombre || 'Sin nombre', company: record.company || record.empresa || '', sector: record.sector || record.niche || '', city: record.city || record.ciudad || '', website: record.website || record.web || '', social_links: record.social_links || record.instagram || '', contact_name: record.contact_name || record.contacto || '', contact_role: record.contact_role || record.cargo || '', phone: record.phone || record.telefono || '', whatsapp: record.whatsapp || '', email: record.email || '', status: record.status || 'new', priority: priorityNames[record.priority] || record.priority || 'media', pipeline_stage: stageNames[record.pipeline_stage] || record.pipeline_stage || 'Prospecto', budget: record.budget || record.revenue_value || '', probability: record.probability || '', next_follow_up_at: record.next_follow_up_at || '', notes: record.notes || '', objections: record.objections || '', call_count: Number(record.call_count || 0), created_at: new Date().toISOString() }; }); commit({ leads: [...incoming, ...leads] }, `${incoming.length} prospectos importados`); };
  const exportCsv = () => { const fields = ['business_name','contact_name','phone','email','city','sector','status','pipeline_stage','budget','probability','next_follow_up_at','notes']; downloadText('ventas.csv', [fields.join(','), ...leads.map((lead) => fields.map((field) => escapeCsv(lead[field])).join(','))].join('\n'), 'text/csv'); };
  return <div className="sales-records"><div className="module-actionbar"><label><Search size={13} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Empresa, contacto, ciudad…" /></label><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">Todos los estados</option>{SALES_STATUSES.map((item) => <option key={item} value={item}>{STATUS_LABELS[item]}</option>)}</select><button onClick={add}><Plus size={12} /> Prospecto</button><label className="file-button"><FileUp size={12} /> Importar CSV<input type="file" accept=".csv,text/csv" onChange={(event) => event.target.files?.[0] && importCsv(event.target.files[0])} /></label><button onClick={exportCsv}><Download size={12} /></button>{selected.size ? <button onClick={() => { commit({ leads: leads.filter((lead) => !selected.has(lead.id)) }, 'Prospectos eliminados'); setSelected(new Set()); }}><Trash2 size={12} /> {selected.size}</button> : null}</div><div className="database-scroll"><table className="smart-table sales-table"><thead><tr><th /><th>Empresa</th><th>Contacto</th><th>Teléfono</th><th>Estado</th><th>Etapa</th><th>Presupuesto</th><th>Probabilidad</th><th>Seguimiento</th></tr></thead><tbody>{visible.map((lead) => <tr key={lead.id}><td><input type="checkbox" checked={selected.has(lead.id)} onChange={() => setSelected((current) => { const next = new Set(current); next.has(lead.id) ? next.delete(lead.id) : next.add(lead.id); return next; })} /></td>{['business_name','contact_name','phone'].map((field) => <td key={field}><input defaultValue={lead[field] || ''} onBlur={(event) => commit({ leads: leads.map((item) => item.id === lead.id ? { ...item, [field]: event.target.value } : item) }, 'Registro comercial actualizado')} /></td>)}<td><select value={lead.status} onChange={(event) => commit({ leads: leads.map((item) => item.id === lead.id ? { ...item, status: event.target.value } : item) }, 'Estado comercial actualizado')}>{SALES_STATUSES.map((item) => <option key={item} value={item}>{STATUS_LABELS[item]}</option>)}</select></td><td><select value={lead.pipeline_stage} onChange={(event) => commit({ leads: leads.map((item) => item.id === lead.id ? { ...item, pipeline_stage: event.target.value } : item) }, 'Etapa comercial actualizada')}>{SALES_STAGES.map((item) => <option key={item}>{item}</option>)}</select></td><td><input type="number" defaultValue={lead.budget || ''} onBlur={(event) => commit({ leads: leads.map((item) => item.id === lead.id ? { ...item, budget: event.target.value } : item) }, 'Presupuesto actualizado')} /></td><td><input type="number" min="0" max="100" defaultValue={lead.probability || ''} onBlur={(event) => commit({ leads: leads.map((item) => item.id === lead.id ? { ...item, probability: event.target.value } : item) }, 'Probabilidad actualizada')} /></td><td><input type="datetime-local" value={lead.next_follow_up_at || ''} onChange={(event) => commit({ leads: leads.map((item) => item.id === lead.id ? { ...item, next_follow_up_at: event.target.value } : item) }, 'Seguimiento actualizado')} /></td></tr>)}</tbody></table></div></div>;
}

function SalesCalls({ content, commit }) {
  const leads = content.leads || []; const calls = content.calls || []; const callable = leads.filter((lead) => !['closed','dead','not_interested','wrong_number'].includes(lead.status)); const [activeId, setActiveId] = useState(callable[0]?.id || ''); const [note, setNote] = useState(''); const [nextCall, setNextCall] = useState(''); const [startedAt, setStartedAt] = useState(Date.now()); const [elapsed, setElapsed] = useState(0); const active = callable.find((lead) => lead.id === activeId) || callable[0];
  useEffect(() => { setStartedAt(Date.now()); setElapsed(0); }, [active?.id]);
  useEffect(() => { const timer = window.setInterval(() => setElapsed(Math.floor((Date.now() - startedAt) / 1000)), 1000); return () => window.clearInterval(timer); }, [startedAt]);
  const log = (outcome) => { if (!active) return; const at = new Date().toISOString(); const call = { id: createId('call'), leadId: active.id, outcome, note, next_call_at: nextCall || null, duration_seconds: elapsed, at }; commit({ calls: [call, ...calls], leads: leads.map((lead) => lead.id === active.id ? { ...lead, status: outcome, call_count: Number(lead.call_count || 0) + 1, last_call_at: at, next_call_at: nextCall || null } : lead) }, `Llamada registrada: ${STATUS_LABELS[outcome]}`); setNote(''); setNextCall(''); const index = callable.findIndex((lead) => lead.id === active.id); setActiveId(callable[index + 1]?.id || callable[0]?.id || ''); };
  useEffect(() => { const outcomes = { ' ': 'no_answer', q: 'interested', w: 'callback', e: 'meeting', r: 'closed', t: 'wrong_number', y: 'not_interested' }; const handler = (event) => { const element = document.activeElement; if (['INPUT','TEXTAREA','SELECT'].includes(element?.tagName) || element?.isContentEditable) return; if (event.key === 'ArrowRight') { const index = callable.findIndex((lead) => lead.id === active?.id); setActiveId(callable[Math.min(index + 1, callable.length - 1)]?.id || ''); } else if (event.key === 'ArrowLeft') { const index = callable.findIndex((lead) => lead.id === active?.id); setActiveId(callable[Math.max(index - 1, 0)]?.id || ''); } else if (outcomes[event.key.toLowerCase()]) { event.preventDefault(); log(outcomes[event.key.toLowerCase()]); } }; window.addEventListener('keydown', handler); return () => window.removeEventListener('keydown', handler); }, [active?.id, callable.length, elapsed, note, nextCall]);
  const duration = `${Math.floor(elapsed / 60)}:${String(elapsed % 60).padStart(2, '0')}`;
  return <div className="sales-calls"><aside><span>Cola priorizada</span>{[...callable].sort((a,b) => ({alta:0,media:1,baja:2}[a.priority] ?? 1)-({alta:0,media:1,baja:2}[b.priority] ?? 1)).map((lead) => <button key={lead.id} className={lead.id === active?.id ? 'is-active' : ''} onClick={() => setActiveId(lead.id)}><strong>{lead.business_name}</strong><small>{lead.priority || 'media'} · {STATUS_LABELS[lead.status]}</small></button>)}</aside><main>{active ? <><header><span>Contacto actual · {duration}</span><h3>{active.business_name}</h3><p>{active.contact_name || 'Sin contacto'} · {active.phone || 'Sin teléfono'} · {active.city || 'Sin ciudad'}</p></header><div className="call-outcomes">{[['no_answer','Espacio'],['interested','Q'],['callback','W'],['meeting','E'],['closed','R'],['wrong_number','T'],['not_interested','Y']].map(([outcome,key]) => <button key={outcome} onClick={() => log(outcome)}><span>{STATUS_LABELS[outcome]}</span><small>{key}</small></button>)}</div><div className="call-followup"><input type="datetime-local" value={nextCall} onChange={(event) => setNextCall(event.target.value)} /><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="Nota, objeción o contexto…" /></div><footer><span>{active.call_count || 0} intentos</span><span>Última llamada: {active.last_call_at ? new Date(active.last_call_at).toLocaleString('es-CO') : 'ninguna'}</span></footer></> : <p>Importa prospectos o créalos en Registros.</p>}</main><aside className="call-history"><span>Historial</span>{calls.filter((call) => !active || call.leadId === active.id).slice(0,12).map((call) => <article key={call.id}><strong>{STATUS_LABELS[call.outcome]}</strong><small>{new Date(call.at).toLocaleString('es-CO')} · {Math.round((call.duration_seconds || 0) / 60)} min</small><p>{call.note || 'Sin nota'}</p></article>)}</aside></div>;
}

function SalesAnalytics({ content }) {
  const leads = content.leads || []; const calls = content.calls || []; const metrics = salesMetrics(leads, calls); const funnel = [{ stage: 'Prospectos', count: metrics.total }, { stage: 'Contactados', count: metrics.contacted }, { stage: 'Conversaciones', count: metrics.conversations }, { stage: 'Interesados', count: metrics.interested }, { stage: 'Reuniones', count: metrics.meetings }, { stage: 'Propuestas', count: metrics.proposals }, { stage: 'Ventas', count: metrics.closed }]; const max = Math.max(1, ...funnel.map((item) => item.count)); const forecast = leads.reduce((sum, lead) => sum + Number(lead.budget || 0) * Number(lead.probability || 0) / 100, 0);
  return <div className="sales-analytics-v1"><div className="sales-kpis">{[['Prospectos',metrics.total],['Llamadas',metrics.calls],['Interesados',metrics.interested],['Cerrados',metrics.closed],['Tasa de contacto',`${metrics.contactRate}%`],['Tasa de interés',`${metrics.interestedRate}%`],['Tasa de reunión',`${metrics.meetingRate}%`],['Tasa de propuesta',`${metrics.proposalRate}%`],['Tasa de cierre',`${metrics.conversionRate}%`],['Duración media',`${metrics.averageDuration} s`]].map(([label,value]) => <article key={label}><span>{label}</span><strong>{value}</strong></article>)}</div><section><div><span>Embudo comercial</span>{funnel.map((item) => <article key={item.stage}><small>{item.stage}</small><i style={{ '--funnel-width': `${item.count / max * 100}%` }} /><strong>{item.count}</strong></article>)}</div><aside><span>Pronóstico ponderado</span><strong>{new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(forecast)}</strong><small>Presupuesto × probabilidad</small></aside></section></div>;
}

export function SalesEditor({ module, onChange }) {
  const content = module.content || {}; const [view, setView] = useState(content.view || 'Registros'); const commit = (next, reason) => onChange({ content: { ...content, ...next } }, reason);
  return <div className="sales-v1"><nav>{['Registros','Llamadas','Analítica'].map((item) => <button key={item} className={view === item ? 'is-active' : ''} onClick={() => { setView(item); commit({ view: item }, `Vista de ventas: ${item}`); }}>{item}</button>)}</nav>{view === 'Registros' ? <SalesRecords module={module} content={content} commit={commit} /> : view === 'Llamadas' ? <SalesCalls content={content} commit={commit} /> : <SalesAnalytics content={content} />}</div>;
}

export const ModuleRenderer = memo(function ModuleRenderer({ project, module, onChange }) {
  if (module.type === 'document') return <DocumentEditor project={project} module={module} onChange={onChange} />;
  if (module.type === 'files') return <FilesEditor project={project} module={module} onChange={onChange} />;
  if (module.type === 'folders') return <FoldersEditor module={module} onChange={onChange} />;
  if (module.type === 'database') return <DatabaseEditor module={module} onChange={onChange} />;
  if (module.type === 'checklist') return <ChecklistEditor module={module} onChange={onChange} />;
  if (module.type === 'goals') return <GoalsEditor module={module} onChange={onChange} />;
  if (module.type === 'notes') return <NotesEditor project={project} module={module} onChange={onChange} />;
  if (module.type === 'ai-tools') return <IntelligenceEditor project={project} module={module} onChange={onChange} />;
  if (module.type === 'subprojects') return <SubprojectsEditor project={project} module={module} onChange={onChange} />;
  if (module.type === 'sales') return <SalesEditor module={module} onChange={onChange} />;
  return <div className="module-unavailable"><Sparkles size={22} /><strong>Próximamente</strong><span>Esta pieza ya pertenece a la visión del sistema, pero todavía no acepta información.</span></div>;
});
